INSERT INTO projects (id, slug, name, description, province, district, neighborhood, latitude, longitude, address_display, thumbnail_url, starting_price, total_floors, total_units, is_featured, created_at) VALUES (1, 'noventa-ari', 'Noventa Ari', 'คอนโดสองทาวเวอร์บนโพเดียมสวนลอยฟ้า ในซอยอารีย์ เดินถึงร้านกาแฟและรถไฟฟ้า BTS อารีย์', 'กรุงเทพมหานคร', 'พญาไท', 'อารีย์', 13.7797, 100.5449, 'ซอยอารีย์ เขตพญาไท กรุงเทพฯ', 'images/projects/noventa-ari.jpg', 3600000, 38, 624, 1, '2026-03-01T00:00:00Z'), (2, 'selvara-on-nut', 'Selvara On Nut', 'คอนโดทาวเวอร์เดียวใกล้ BTS อ่อนนุช ห้องหันรับลมตะวันออก–ตะวันตก มีสระว่ายน้ำบนโพเดียม', 'กรุงเทพมหานคร', 'พระโขนง', 'อ่อนนุช', 13.7056, 100.6011, 'ถนนสุขุมวิท 77 เขตพระโขนง กรุงเทพฯ', 'images/projects/selvara-on-nut.jpg', 2760000, 32, 378, 0, '2026-05-15T00:00:00Z'), (3, 'kaelo-khae-rai', 'Kaelo Khae Rai', 'คอนโดสองอาคารใกล้แยกแคราย เดินทางสะดวกด้วยรถไฟฟ้าสายสีม่วง เหมาะกับครอบครัวเล็ก', 'นนทบุรี', 'เมืองนนทบุรี', 'แคราย', 13.859, 100.5285, 'ถนนงามวงศ์วาน อำเภอเมืองนนทบุรี จังหวัดนนทบุรี', 'images/projects/kaelo-khae-rai.jpg', 2040000, 25, 390, 0, '2026-01-20T00:00:00Z'), (4, 'thalora-rangsit', 'Thalora Rangsit', 'คอนโดโลว์ไรส์ราคาเข้าถึงง่าย ใกล้ห้างใหญ่และมหาวิทยาลัยย่านรังสิต', 'ปทุมธานี', 'ธัญบุรี', 'รังสิต', 13.9888, 100.6178, 'ถนนรังสิต-นครนายก อำเภอธัญบุรี จังหวัดปทุมธานี', 'images/projects/thalora-rangsit.jpg', 1150000, 20, 204, 0, '2025-11-10T00:00:00Z'), (5, 'marivo-paknam', 'Marivo Paknam', 'คอนโดห้องกว้างใกล้ปากแม่น้ำเจ้าพระยา ห้องมุมขนาดใหญ่ เดินทางเข้าเมืองด้วย BTS สายสุขุมวิท', 'สมุทรปราการ', 'เมืองสมุทรปราการ', 'ปากน้ำ', 13.5993, 100.5968, 'ถนนสุขุมวิท อำเภอเมืองสมุทรปราการ จังหวัดสมุทรปราการ', 'images/projects/marivo-paknam.jpg', 1680000, 30, 250, 0, '2026-08-05T00:00:00Z');
